LESSONS = [
 dict(id='X01', title='动作复用：先选兼容资源，再做少量适配', prereq=['I02'], concepts='C21/C26', goal='筛选可复用动作包，明确导入、重定向与授权检查。', m=['区分动作片段、骨架、蒙皮及根位移来源。','先试一段动作，再决定批量复用是否值得。'], k=['Retarget、In-place、Root Motion、IK知道用途。'], stop='不从零做武打动画，不重造重定向算法；可购买/使用资源不等于可公开再分发原文件。',
 body=['复用不是把任意动画拖到任意人物上。骨架映射、静止姿态、比例和根位移会影响结果；先试最小动作，再扩大。','优先选择来源清楚、目标骨架明确的资源。Mixamo及其他服务的可用账号、地区和许可需按使用时官方条件核对；本课不依赖必须访问某一个服务，也不使用游戏提取资源。'],
 initial='三个动作资源说明卡：同骨架、可重定向、无来源；简化关节预览，不附第三方动作文件。', controls='选择资源、A/T参考姿态、根位移开关、循环预览、观察脚底。', steps=['先按授权和兼容筛掉高风险包。','试待机和一步行走或单次动作，检查脚滑、骨骼方向和位移。','写少量适配/换资源的决策，并保存来源与测试状态。'], feedback='显示原数据与适配结果对照；动作能播放不自动等于碰撞和玩法正确。', failure='故障：脚本移动与动画根位移同时生效导致双倍移动；先明确一个位移来源。', reset='回到原角色与静止姿态，保留原动画文件只读。',
 ui=['Godot：动画预览、速度、片段与骨架映射检查。','Blender会定位：Dope Sheet/Action、NLA；只为预览和少量调整。','按需查：Retarget/BoneMap、根位移提取、IK修正。'],
 questions=[('P','动画能播就说明适合当前角色吗？','不一定，还需检查变形、比例、脚滑、位移和授权。','看脚底与根节点。'),('D','人物位移像加倍，先检查什么？','是否脚本和动作都提供根位移；先明确责任，再测试。','谁在移动根？'),('T','动作换到更矮的卡通人物要复测什么？','接触点、脚滑、肢体穿插、根位移和可读性；不必重做全部动画。','比例改变影响哪里？'),('K','In-place大致是什么意思？','动作主要原地播放，位移可由控制器提供；具体片段仍要检查。','别只信文件名。')],
 remember=['先试一段再导整包。','明确谁控制根位移。','来源、使用和再分发逐项核对。'], recall=['I01','I02','B09'], practice='真实资源获取与适配留配套阶段；教师提供匿名说明卡即可先完成选择训练。', sources=['retarget','mixamo','quaternius']),
 dict(id='X02', title='武打表现选修：复用片段，打磨节奏与反馈', prereq=['X01','B11'], concepts='ART09/C16/C18/C21', goal='用现成动作片段设计一次清楚的起势、接触、恢复，不研究复杂格斗系统。', m=['识别起势、接触点和收势，用少量时间调整提升可读性。','区分动作画面、命中判定和反馈触发，并做重复输入检查。'], k=['Anticipation、Follow-through、Hit stop、Blend是表现词；不用全部采用。'], stop='不要求从零制作武打动作、专业动捕或复杂连招；本课只做表现与复用判断。',
 body=['好看的武打片段不等于可用攻击。玩家要能读出准备、接触与恢复；动画时间和判定时间要对齐，但判定不由模型看起来碰上自动发生。','可以从兼容片段裁剪、调速、过渡和少量接触修正。过度调速会损害动作重量和脚底稳定；复杂坏片段可以换资源，不强迫初学者成为动画师。'],
 initial='用原创抽象角色或许可允许的单次挥动片段；时间条标起势/接触/恢复；木桩为虚构目标；默认无命中逻辑。', controls='整体速度0.8到1.2倍、接触事件时间、过渡0到0.2秒、反馈开关、重复输入。', steps=['先在时间条指出预计接触时刻，不看答案。','小幅调速，再对齐一次命中与反馈，避免反馈先于事件。','检查空挥不计命中、同次攻击不重复奖励、动作结束能恢复。'], feedback='示意时间线不冒充真实引擎动画；非真实战斗教学。若只有静态资料，用帧序列判断代替播放，不伪造动作资源。', failure='故障：只因播放动画就自动命中，空挥也扣目标状态；拆分动画、判定与反馈。', reset='恢复片段速度、时间标记、目标状态与反馈。',
 ui=['常用：片段起止、速度、过渡和事件标记。','会定位：AnimationPlayer/Tree、Dope Sheet/Action或NLA。','按需查：复杂曲线、动捕清理、IK和高级连招框架。'],
 questions=[('P','剑的模型看起来碰到目标就等于命中吗？','不自动等于，需要明确玩法判定并与视觉协调。','画面和规则分开。'),('D','空挥也掉目标生命，先查哪里？','命中事件是否错误绑定为动画开始；检查条件与目标。','事件发生的条件是什么？'),('T','动作换成长柄道具，需要调整和验证什么？','接触距离、时机、目标判定与穿插，不只更换模型。','长度改变哪条约束？'),('K','Anticipation有什么用途？','动作前的准备帮助读意图；不要求复杂原创动画。','玩家何时知道要发生什么？')],
 remember=['复用动作不等于复用所有判定。','节奏先清楚，再加特效。','少量适配，不为坏资源无限返工。'], recall=['B10','B11','I02'], practice='动作资源、引擎判定与后续演示单独制作，不进入基础单机收集毕业门槛。', sources=['anim','retarget','mixamo'])
]
